"""Adversarial acceptance tests: source examples must be generated by operations."""
from __future__ import annotations

from copy import deepcopy
from fractions import Fraction
import json
from pathlib import Path
import unittest

from mechanistic_replay import run_manifest, run_case, apply_operation, evaluate


HERE = Path(__file__).resolve().parent
INPUT = json.loads((HERE / "MECHANISM_CASES.json").read_text(encoding="utf-8"))
CASES = {c["case_id"]: c for c in INPUT["cases"]}
REPORT = run_manifest(INPUT)
BY_ID = {r["case_id"]: r for r in REPORT["cases"]}


def probe(case_id: str, name: str = None) -> dict:
    entries = BY_ID[case_id]["probes"]
    return next(p for p in entries if p["probe"] == name) if name else entries[0]


class AuthorOriginalMechanismAcceptances(unittest.TestCase):
    def test_full_author_corpus_register_has_fourteen_mechanism_cases(self):
        self.assertEqual(REPORT["case_count"], 14)
        self.assertEqual(set(CASES), set(BY_ID))
        self.assertTrue(all(r["evidence_tier"] == "AUTHOR_HYPOTHETICAL_TOY"
                            and r["initial_valid"] == "PASS" for r in BY_ID.values()))

    def test_banana_additional_transport_is_a_real_tradeoff(self):
        result = probe("EX-BAN-02")
        self.assertEqual(result["admissibility"], "PASS")
        self.assertEqual(result["candidate_facts"]["received"], "1")
        self.assertEqual(result["candidate_facts"]["held"], "0")
        self.assertEqual(result["candidate_facts"]["transport"], "3")
        self.assertEqual(result["candidate_stages"][0]["comparison"]["status"], "TRADEOFF")

    def test_banana_origin_K2_vs_K3_and_authority_is_unresolved(self):
        result = probe("EX-BAN-01")
        self.assertEqual(result["candidate_facts"]["route_km"], "0")
        self.assertEqual(result["candidate_facts"]["local_consumed"], "1")
        self.assertEqual(result["candidate_stages"][0]["comparison"]["status"],
                         "DOMINATES_ON_DECLARED_AXES")
        self.assertEqual(result["candidate_stages"][1]["comparison"]["status"], "TRADEOFF")
        self.assertEqual(result["admissibility"], "UNKNOWN")
        self.assertEqual(result["actually_committed_facts"], result["initial_facts"])

    def test_dana_credit_of_new_benefit_has_no_fabricated_baseline_share(self):
        declined = probe("EX-BAN-03", "attribution_refusal")
        accepted = probe("EX-BAN-03", "attribution_accepted_control")
        self.assertEqual(declined["admissibility"], "FAIL")
        self.assertEqual(accepted["admissibility"], "PASS")
        self.assertEqual(declined["candidate_facts"]["donor_credit"], "1/10")
        self.assertEqual(accepted["candidate_facts"]["donor_credit"], "1")
        self.assertEqual(declined["candidate_stages"][0]["comparison"]["status"],
                         "DOMINATES_ON_DECLARED_AXES")
        self.assertEqual(declined["candidate_stages"][1]["comparison"]["status"],
                         "DOMINATES_ON_DECLARED_AXES")
        self.assertEqual(declined["candidate_stages"][2]["comparison"]["status"],
                         "NOT_ESTABLISHED")
        self.assertEqual(declined["actually_committed_facts"], declined["initial_facts"])

    def test_original_two_bananas_S0_S1_S2_and_stipulated_W(self):
        generated = probe("EX-BAN-04", "S0_S1_S2_conditional")
        self.assertEqual(generated["admissibility"], "UNKNOWN")
        self.assertEqual(generated["steps"][0]["candidate_after"],
                         {"child": "0", "holder": "1", "produced": "2", "waste": "1"})
        self.assertEqual(generated["candidate_facts"],
                         {"child": "1", "holder": "1", "produced": "2", "waste": "0"})
        self.assertEqual(generated["actually_committed_facts"], generated["steps"][0]["candidate_after"])
        self.assertEqual(CASES["EX-BAN-04"]["source_stipulated_welfare"]["S1"],
                         {"B": 5, "F": 7, "W": -2})

    def test_friday_robinson_1_999_is_generated_by_conserved_transfers(self):
        result = probe("EX-ROBIN-01")
        self.assertEqual(result["candidate_facts"]["v_coco"], "1")
        self.assertEqual(result["candidate_facts"]["r_coco"], "999")
        self.assertEqual(result["candidate_facts"]["v_fish"], "1")
        self.assertEqual(result["candidate_facts"]["r_fish"], "999")
        self.assertEqual(result["candidate_facts"]["coco_lost"], "0")
        self.assertEqual(result["candidate_facts"]["fish_lost"], "0")
        self.assertEqual(result["admissibility"], "FAIL")
        self.assertEqual(result["candidate_stages"][0]["comparison"]["status"],
                         "DOMINATES_ON_DECLARED_AXES")
        self.assertEqual(result["candidate_stages"][1]["comparison"]["status"], "NOT_ESTABLISHED")

    def test_ministry_700_to_2_is_a_conditional_not_a_pareto_proof(self):
        result = probe("EX-MIN-01")
        self.assertEqual(result["candidate_facts"]["applications"], "2")
        self.assertEqual(result["candidate_stages"][0]["comparison"]["status"],
                         "DOMINATES_ON_DECLARED_AXES")
        self.assertEqual(result["candidate_stages"][1]["comparison"]["status"],
                         "NOT_ESTABLISHED")
        self.assertEqual(result["admissibility"], "UNKNOWN")

    def test_apple_utility_profile_requires_nonmonotone_joint_bridge(self):
        negative = probe("EX-APPLE-01", "local_extra_apple_rejected")
        bridge = probe("EX-APPLE-01", "hypothetical_joint_jump")
        self.assertEqual(negative["candidate_facts"]["quantity"], "4")
        self.assertEqual(negative["candidate_facts"]["utility"], "7")
        self.assertEqual(negative["admissibility"], "FAIL")
        self.assertEqual(bridge["candidate_facts"]["quantity"], "8")
        self.assertEqual(bridge["candidate_facts"]["utility"], "10")
        self.assertEqual(bridge["admissibility"], "PASS")
        self.assertEqual(bridge["steps"][0]["mode"], "joint")

    def test_binary_joint_is_possible_but_each_unilateral_breaks_equality(self):
        actions = {x["probe"]: x for x in BY_ID["EX-LINEAR-01"]["probes"]}
        self.assertEqual(actions["unilateral_a_fails"]["admissibility"], "FAIL")
        self.assertEqual(actions["unilateral_b_fails"]["admissibility"], "FAIL")
        self.assertEqual(actions["joint_positive_control"]["admissibility"], "PASS")
        self.assertEqual(actions["joint_positive_control"]["candidate_facts"],
                         {"x1": "1", "x2": "1"})

    def test_credit_7_4_is_physically_infeasible(self):
        result = probe("EX-CREDIT-01")
        self.assertEqual(result["candidate_facts"]["share_a"], "7")
        self.assertEqual(result["candidate_facts"]["share_b"], "3")
        self.assertEqual(result["steps"][0]["candidate_after"]["share_b"], "4")
        self.assertEqual(result["steps"][0]["technical"], "FAIL")
        self.assertEqual(result["admissibility"], "FAIL")

    def test_freely_chosen_and_nonconsented_solidarity_stay_distinct(self):
        self.assertEqual(probe("EX-SOLIDAR-01", "no_consent_not_authorized")["admissibility"], "UNKNOWN")
        self.assertEqual(probe("EX-SOLIDAR-01", "hypothetical_consent")["admissibility"], "PASS")

    def test_unobserved_oranges_and_student_remain_non_numeric(self):
        for case_id in ("EX-ORANGE-01", "EX-HUMAN-01"):
            with self.subTest(case_id=case_id):
                result = probe(case_id)
                self.assertEqual(result["admissibility"], "UNKNOWN")
                self.assertEqual(result["candidate_stages"][0]["comparison"]["status"], "NOT_ESTABLISHED")

    def test_X_minus_200_repair_is_conditional_and_not_authorized(self):
        result = probe("EX-SUPER-01")
        self.assertEqual(result["initial_facts"]["delivered"], "800")
        self.assertEqual(result["candidate_facts"]["delivered"], "1000")
        self.assertEqual(result["admissibility"], "UNKNOWN")

    def test_source_pilot_marketing_compensation_is_derived_not_invented_55(self):
        raw = probe("EX-BUSINESS-01", "raw_70_not_pareto")
        paid = probe("EX-BUSINESS-01", "source_40_transfer_and_12_cost")
        self.assertEqual(raw["candidate_facts"]["net_marketing"], "60")
        self.assertEqual(raw["candidate_facts"]["net_operations"], "40")
        self.assertEqual(raw["candidate_facts"]["net_systems"], "-30")
        self.assertEqual(raw["admissibility"], "FAIL")
        self.assertEqual(paid["candidate_facts"]["transfer_to_systems"], "40")
        self.assertEqual((paid["candidate_facts"]["net_marketing"],
                          paid["candidate_facts"]["net_operations"],
                          paid["candidate_facts"]["net_systems"]), ("14", "36", "8"))
        self.assertEqual(sum(int(paid["candidate_facts"][key])
                             for key in ("net_marketing", "net_operations", "net_systems")), 58)
        self.assertEqual(paid["admissibility"], "UNKNOWN")


class ReusableOperationAdversarialTests(unittest.TestCase):
    def test_mutating_physical_production_changes_outputs(self):
        altered = deepcopy(CASES["EX-BAN-04"])
        altered["actions"][0]["delta"] = {"produced": 3, "holder": 1, "waste": 2}
        altered["actions"][1]["requires"] = {"produced": 3, "waste": 2}
        report = run_case(altered)
        candidate = next(p for p in report["probes"] if p["probe"] == "S0_S1_S2_conditional")
        self.assertEqual(candidate["candidate_facts"],
                         {"child": "1", "holder": "1", "produced": "3", "waste": "1"})

    def test_conserved_transfer_cannot_take_more_than_source_holds(self):
        altered = deepcopy(CASES["EX-BAN-04"])
        altered["actions"][1]["transfers"][0]["amount"] = 2
        report = run_case(altered)
        candidate = next(p for p in report["probes"] if p["probe"] == "S0_S1_S2_conditional")
        self.assertEqual(candidate["admissibility"], "FAIL")
        self.assertEqual(candidate["candidate_facts"]["waste"], "1")
        self.assertEqual(candidate["steps"][-1]["technical"], "FAIL")

    def test_measured_unknown_is_not_zero_and_credit_denominator_zero_stays_unknown(self):
        self.assertIsNone(evaluate({"op":"unknown"}, {"a": Fraction(1)}))
        self.assertIsNone(evaluate({"op":"ratio", "fields":["a"],"denominator_fields":["b"]},
                                   {"a":Fraction(0),"b":Fraction(0)}))

    def test_third_party_water_reuse_without_case_name_in_engine(self):
        scenario = {
            "case_id":"EXTERNAL-WATER","source_anchor":"external://declared-meter",
            "evidence_tier":"AUTHOR_HYPOTHETICAL_TOY",
            "initial":{"litres":10,"service":2},
            "dimensions":{"water":{"direction":"min","unit":"litres","formula":{"op":"field","field":"litres"}},
                          "service":{"direction":"max","unit":"units","formula":{"op":"field","field":"service"}}},
            "actions":[{"id":"save","delta":{"litres":-2},"guards":[]}],
            "probes":[{"id":"save_water","actions":["save"]}],
            "stages":[{"id":"technical","axes":["water","service"]}],
            "nonnegative_fields":["litres","service"]
        }
        result = run_case(scenario)["probes"][0]
        self.assertEqual(result["admissibility"], "PASS")
        self.assertEqual(result["candidate_facts"]["litres"], "8")
        self.assertEqual(result["candidate_stages"][0]["comparison"]["status"], "DOMINATES_ON_DECLARED_AXES")

    def test_invalid_source_or_gate_cannot_be_relabelled_empirical(self):
        broken = deepcopy(CASES["EX-BAN-04"])
        broken["evidence_tier"] = "REAL_HUMAN_OBSERVATION"
        with self.assertRaisesRegex(ValueError,"empirical"):
            run_case(broken)
        broken = deepcopy(CASES["EX-BAN-01"])
        broken["actions"][0]["guards"][0]["source_of_status"] = ""
        with self.assertRaisesRegex(ValueError,"provenance"):
            run_case(broken)

    def test_boolean_nonnumeric_or_undefined_operation_rejected(self):
        with self.assertRaises(ValueError):
            apply_operation({"a":Fraction(1)},{"id":"bad","delta":{"a":True}})
        with self.assertRaisesRegex(ValueError,"unknown physical field"):
            apply_operation({"a":Fraction(1)},{"id":"bad","delta":{"b":3}})
        broken = deepcopy(CASES["EX-BAN-01"])
        broken["probes"][0]["actions"]=["does_not_exist"]
        with self.assertRaisesRegex(ValueError,"undefined operation"):
            run_case(broken)

    def test_deterministic_replay_regenerates_same_output(self):
        first = json.dumps(run_manifest(INPUT),sort_keys=True,separators=(",",":"))
        second = json.dumps(run_manifest(INPUT),sort_keys=True,separators=(",",":"))
        self.assertEqual(first, second)


if __name__ == "__main__":
    unittest.main()
